            jdbc.update("DELETE FROM incident_task_blockers WHERE id = ?", id);
        }
        for (Long id : toRepoint) {
            jdbc.update("UPDATE incident_task_blockers SET blocker_incident_id = ? WHERE id = ?",
                    survivingIncidentId, id);
